// Goroutine to send jobs
go func() {
	for i := 0; i < numJobs; i++ {
		jobs <- Job{ID: i}
	}
	close(jobs) // Close the jobs channel after all jobs are sent
}()

// Goroutine to close results channel after all workers are done
go func() {
	wg.Wait() // Wait for all workers to finish
	close(results) // Safely close results channel
}()

// Consume results concurrently
var finalProcessedCount int
for range results {
	finalProcessedCount++
}

return int(processedCount), nil
